	const candidate = value as { resolutions?: unknown; pending?: unknown };
	return {
		resolutions: Array.isArray(candidate.resolutions)
			? candidate.resolutions.filter(isReviewResolution)
			: [],
		pending: Array.isArray(candidate.pending)
