	sessionId?: string;
}

export interface LixFileServiceOptions {
	agentReview?: AgentReviewSource;
}

export type EntryKind = "file" | "directory";

export interface EntrySummary {
	kind: EntryKind;
	path: string;
	name: string;
	changeId: string;
	updatedAt: string;
	size?: number | null;
}

export interface FileSnapshot {
