			options.authorizeWorkspace ?? authorizeWorkspaceWithSupabase;
		if (!env.SLATEDB_CONTAINER && !options.workspaceFetch) {
			return new Response("Workspace storage is not configured\n", {
				status: 500,
			});
		}
