		const telemetry = (options.createMcpTelemetry ?? createMcpTelemetrySession)(
			env,
			{
				userId: authResult.auth.userId,
				clientId: authResult.auth.clientId,
				isDemo: authResult.auth.isDemo,
			},
		);
