	POSTHOG_HOST?: string;
	POSTHOG_ENVIRONMENT?: string;
}

type AuthorizeWorkspace = (
	workspaceId: string,
	user: McpUser,
	env: WorkerLixRuntimeEnv,
) => Promise<Response | null>;

export interface WorkerLixRuntimeClientOptions {
	fetcher?: typeof fetch;
	retryDelay?: ContainerRetryDelay;
	retryRandom?: () => number;
	signal?: AbortSignal;
	workspaceFetch?: (workspaceId: string, request: Request) => Promise<Response>;
	workspaceSummaries?: ReadonlyArray<WorkspaceSummary>;
}

interface WorkspaceLixSession {
	lix: Lix;
	queue: Promise<void>;
}

export class WorkerLixRuntimeClient implements LixRuntimeClient {
	private readonly env: WorkerLixRuntimeEnv;
	private readonly user: McpUser;
	private readonly authorizeWorkspace: AuthorizeWorkspace;
	private readonly fetcher: typeof fetch;
	private readonly retryDelay: ContainerRetryDelay | undefined;
	private readonly retryRandom: (() => number) | undefined;
	private readonly signal: AbortSignal | undefined;
	private readonly workspaceFetch:
		| ((workspaceId: string, request: Request) => Promise<Response>)
		| undefined;
	private readonly workspaceSummaries:
		| ReadonlyArray<WorkspaceSummary>
		| undefined;
	private readonly sessions = new Map<string, Promise<WorkspaceLixSession>>();
	private closePromise: Promise<void> | undefined;
	private closed = false;

	constructor(
		env: WorkerLixRuntimeEnv,
		user: McpUser,
		authorizeWorkspace: AuthorizeWorkspace,
		options: WorkerLixRuntimeClientOptions = {},
	) {
		this.env = env;
		this.user = user;
		this.authorizeWorkspace = authorizeWorkspace;
		this.fetcher = options.fetcher ?? fetch;
		this.retryDelay = options.retryDelay;
		this.retryRandom = options.retryRandom;
		this.signal = options.signal;
		this.workspaceFetch = options.workspaceFetch;
		this.workspaceSummaries = options.workspaceSummaries;
	}

	async listWorkspaces(): Promise<Array<WorkspaceSummary>> {
		if (this.workspaceSummaries) {
			return this.workspaceSummaries.map((workspace) => ({
				...workspace,
				organization: { ...workspace.organization },
			}));
		}
		const supabaseUrl = requiredEnv(this.env.SUPABASE_URL, "SUPABASE_URL");
		const publishableKey = requiredEnv(
			this.env.SUPABASE_PUBLISHABLE_KEY,
			"SUPABASE_PUBLISHABLE_KEY",
		);
		const headers = {
			apikey: publishableKey,
			Authorization: `Bearer ${this.user.token}`,
			Accept: "application/json",
		};
		const organizationsUrl = new URL("/rest/v1/organizations", supabaseUrl);
		organizationsUrl.searchParams.set("select", "id,name,handle");
		organizationsUrl.searchParams.set("order", "created_at.asc");
		const workspacesUrl = new URL("/rest/v1/workspaces", supabaseUrl);
		workspacesUrl.searchParams.set("select", "id,organization_id,name,slug");
		workspacesUrl.searchParams.set("order", "created_at.asc");

		const fetcher = this.fetcher;
		let organizationsResponse: Response;
		let workspacesResponse: Response;
		try {
			[organizationsResponse, workspacesResponse] = await Promise.all([
				fetcher(organizationsUrl, { headers }),
				fetcher(workspacesUrl, { headers }),
			]);
		} catch (caught) {
			console.error("LixRay workspace discovery fetch failed", {
				error: errorDetails(caught),
			});
			throw new FileServiceError(
				"upstream_error",
				"Workspace discovery is unavailable.",
			);
		}
		if (!organizationsResponse.ok || !workspacesResponse.ok) {
			throw new FileServiceError(
				"upstream_error",
				"Workspace discovery is unavailable.",
			);
		}
		const organizations = asRows(await organizationsResponse.json());
		const workspaces = asRows(await workspacesResponse.json());
		const organizationsById = new Map(
			organizations.flatMap((row) => {
				const id = stringField(row, "id");
				const name = stringField(row, "name");
				const handle = stringField(row, "handle");
				return id && name && handle ? [[id, { name, handle }] as const] : [];
			}),
		);

		return workspaces.flatMap((row): Array<WorkspaceSummary> => {
			const id = stringField(row, "id");
			const name = stringField(row, "name");
			const slug = stringField(row, "slug");
			const organizationId = stringField(row, "organization_id");
			const organization = organizationId
				? organizationsById.get(organizationId)
				: undefined;
			return id && name && slug && organizationId && organization
				? [
						{
							id,
							name,
							slug,
							organization: { id: organizationId, ...organization },
						},
					]
				: [];
		});
	}

	async activeBranchId(workspaceId: string): Promise<string> {
		try {
			const session = await this.session(workspaceId);
			return await this.enqueueSession(session, () =>
				session.lix.activeBranchId(),
			);
		} catch (caught) {
			throw asFileServiceError(caught);
		}
	}

	async switchBranch(
		workspaceId: string,
		branchId: string,
	): Promise<{ branchId: string }> {
		try {
			const session = await this.session(workspaceId);
			return await this.enqueueSession(session, () =>
				session.lix.switchBranch({ branchId }),
			);
		} catch (caught) {
			throw asFileServiceError(caught);
		}
	}

	async execute(
		workspaceId: string,
		request: ExecuteRequest,
	): Promise<ExecuteResponse> {
		try {
			const session = await this.session(workspaceId);
			return await this.enqueueSession(session, async () => {
				return encodeExecuteResult(
					await session.lix.execute(
						request.sql,
						(request.params ?? []).map(decodeWireParam),
						request.options,
					),
				);
			});
		} catch (caught) {
			throw asFileServiceError(caught);
		}
	}

	async executeBatch(
		workspaceId: string,
		request: ExecuteBatchRequest,
	): Promise<ExecuteScriptResponse> {
		try {
			const session = await this.session(workspaceId);
			return await this.enqueueSession(session, async () => {
				const results = await session.lix.executeBatch(
					request.statements.map((statement) => ({
						sql: statement.sql,
						params: (statement.params ?? []).map(decodeWireParam),
					})),
					request.options,
				);
				return { results: results.map(encodeExecuteResult) };
			});
		} catch (caught) {
			throw asFileServiceError(caught);
		}
	}

	async close(): Promise<void> {
		this.closePromise ??= (async () => {
			this.closed = true;
			const sessions = [...this.sessions.values()];
			this.sessions.clear();
			await Promise.all(
				sessions.map(async (pending) => {
					try {
						const session = await pending;
						await session.queue;
						await session.lix.close();
					} catch {
						// A failed open or operation has no live session to close.
					}
				}),
			);
		})();
		return this.closePromise;
	}

	private session(workspaceId: string): Promise<WorkspaceLixSession> {
		if (this.closed) {
			throw new FileServiceError("upstream_error", "Lix client is closed.");
		}
		let pending = this.sessions.get(workspaceId);
		if (pending) return pending;
		pending = this.openSession(workspaceId).catch((error) => {
			this.sessions.delete(workspaceId);
			throw error;
		});
		this.sessions.set(workspaceId, pending);
		return pending;
	}

	private async openSession(workspaceId: string): Promise<WorkspaceLixSession> {
		const lix = await openLix({
			server: {
				mode: "remote",
				url: "https://mcp.lixray.invalid",
				fetch: (input, init) => this.protocolFetch(workspaceId, input, init),
			},
		});
		return {
			lix,
			queue: Promise.resolve(),
		};
	}

	private async enqueueSession<T>(
		session: WorkspaceLixSession,
		operation: () => Promise<T>,
	): Promise<T> {
		const result = session.queue.then(operation, operation);
		session.queue = result.then(
			() => undefined,
			() => undefined,
		);
		return result;
	}

	private async protocolFetch(
		workspaceId: string,
		input: RequestInfo | URL,
		init?: RequestInit,
	): Promise<Response> {
		const request = new Request(input, {
			...init,
			signal: init?.signal ?? this.signal,
		});
		const path = canonicalProtocolPath(new URL(request.url));
		if (path === null) return new Response("Not found\n", { status: 404 });
		return this.workspaceResponse(workspaceId, path, request);
	}

	private async workspaceResponse(
		workspaceId: string,
		path: string,
		request: Request,
	): Promise<Response> {
		const authorizationFailure = await this.authorizeWorkspace(
			workspaceId,
			this.user,
			this.env,
		);
		if (authorizationFailure) return authorizationFailure;

		const url = new URL(request.url);
		url.pathname = path;
		const rewritten = new Request(url, request);
		const headers = new Headers(rewritten.headers);
		headers.delete("authorization");
		const template = new Request(rewritten, { headers });
		if (this.workspaceFetch) {
			return this.workspaceFetch(workspaceId, template);
		}

		const containerNamespace = this.env.SLATEDB_CONTAINER;
		if (!containerNamespace) {
			return new Response("Workspace storage is not configured.\n", {
				status: 500,
			});
		}
		const workspacePath = `/workspaces/${encodeURIComponent(workspaceId)}${path}`;
		url.pathname = workspacePath;
		const containerTemplate = new Request(url, template);
		try {
			return await fetchContainerWithRetry({
				namespace: containerNamespace,
				workspaceId,
				operation: `${request.method} ${workspacePath}`,
				envVars: containerEnv(this.env),
				createRequest: () => containerTemplate.clone() as unknown as Request,
				requestReplay: workspaceRequestReplay(request.method, path),
				signal: request.signal,
				retryDelay: this.retryDelay,
				retryRandom: this.retryRandom,
				onRetry: logTransientContainerRetry,
			});
		} catch (caught) {
			if (request.signal.aborted) {
				return Response.json(
					{
						error: {
							code: "LIX_REMOTE_CANCELLED",
							message: "Workspace storage request was cancelled.",
						},
					},
					{ status: 499 },
				);
			}
			console.error("LixRay container request failed", {
				workspaceId,
				path,
				error: containerErrorDetails(caught),
			});
			throw caught;
		}
	}
}

function canonicalProtocolPath(url: URL): string | null {
	const marker = "/lix/v1/";
	const markerIndex = url.pathname.indexOf(marker);
	if (markerIndex === -1) return null;
	return url.pathname.slice(markerIndex);
}

function workspaceRequestReplay(
	method: string,
	path: string,
): "safe" | "unsafe" {
	if (["GET", "HEAD", "OPTIONS"].includes(method.toUpperCase())) return "safe";
	return path.endsWith("/observe") || path.endsWith("/observe/multiplex")
		? "safe"
		: "unsafe";
}

function decodeWireParam(
	value: NonNullable<ExecuteRequest["params"]>[number],
): SqlParam {
	switch (value.kind) {
		case "null":
			return Value.null();
		case "bool":
			return Value.boolean(value.value);
		case "int":
			return Value.integer(value.value);
		case "float":
			return Value.real(value.value);
		case "text":
			return Value.text(value.value);
		case "json":
			return Value.json(value.value as JsonValue);
		case "blob":
			return Value.blob(base64ToBytes(value.base64));
	}
}

function encodeExecuteResult(result: LixExecuteResult): ExecuteResponse {
	return {
		columns: [...result.columns],
		rows: result.rows.map((row) =>
			result.columns.map((column) => encodeLixValue(row.value(column))),
		),
		rowsAffected: result.rowsAffected,
		notices: result.notices.map((notice) => ({ ...notice })),
	};
}

type LixResultValue = ReturnType<LixExecuteResult["rows"][number]["value"]>;

function encodeLixValue(
	value: LixResultValue,
): ExecuteResponse["rows"][number][number] {
	const jsValue = value.toJS();
	switch (value.kind) {
		case "null":
			return { kind: "null", value: null };
		case "boolean":
			return { kind: "bool", value: jsValue as boolean };
		case "integer":
			return { kind: "int", value: jsValue as number };
		case "real":
			return { kind: "float", value: jsValue as number };
		case "text":
			return { kind: "text", value: jsValue as string };
		case "json":
			return { kind: "json", value: jsValue };
		case "blob": {
			const bytes = value.asBytes();
			if (!bytes) {
				throw new FileServiceError(
					"upstream_error",
					"Lix returned an invalid blob value.",
				);
			}
			return { kind: "blob", base64: bytesToBase64(bytes) };
		}
	}
}

function asFileServiceError(caught: unknown): FileServiceError {
	if (caught instanceof FileServiceError) return caught;
	const error =
		caught && typeof caught === "object"
			? (caught as Record<string, unknown>)
			: undefined;
	const status = typeof error?.status === "number" ? error.status : undefined;
	const rawCode = typeof error?.code === "string" ? error.code : undefined;
	const transportError =
		rawCode === "LIX_REMOTE_CANCELLED" ||
		rawCode === "LIX_REMOTE_PROTOCOL_ERROR" ||
		rawCode === "LIX_REMOTE_REQUEST_FAILED" ||
		rawCode === "LIX_REMOTE_UNAVAILABLE";
	const details =
		error?.details &&
		typeof error.details === "object" &&
		!Array.isArray(error.details)
			? { ...(error.details as Record<string, unknown>) }
			: {};
	if (status !== undefined) details.status = status;
	if (typeof error?.hint === "string") details.hint = error.hint;
	const code: FileServiceErrorCode =
		status === 403 || status === 404
			? "not_found"
			: rawCode?.startsWith("LIX_") && !transportError
				? (rawCode as `LIX_${string}`)
				: "upstream_error";
	return new FileServiceError(
		code,
		caught instanceof Error ? caught.message : "Lix request failed.",
		Object.keys(details).length === 0 ? undefined : details,
	);
}

function containerEnv(env: WorkerLixRuntimeEnv): Record<string, string> {
	const vars: Record<string, string> = {};
	for (const [target, source] of [
		["S3_ENDPOINT", "R2_ENDPOINT"],
		["S3_BUCKET", "R2_BUCKET"],
		["S3_ACCESS_KEY_ID", "R2_ACCESS_KEY_ID"],
		["S3_SECRET_ACCESS_KEY", "R2_SECRET_ACCESS_KEY"],
		["S3_REGION", "R2_REGION"],
		["S3_PREFIX", "S3_PREFIX"],
		["S3_ALLOW_HTTP", "S3_ALLOW_HTTP"],
		["SLATEDB_CACHE_DIR", "SLATEDB_CACHE_DIR"],
		["SLATEDB_CACHE_MAX_BYTES", "SLATEDB_CACHE_MAX_BYTES"],
		["SLATEDB_BLOCK_CACHE_BYTES", "SLATEDB_BLOCK_CACHE_BYTES"],
		["SLATEDB_METADATA_CACHE_BYTES", "SLATEDB_METADATA_CACHE_BYTES"],
		["POSTHOG_PROJECT_TOKEN", "POSTHOG_PROJECT_TOKEN"],
		["POSTHOG_HOST", "POSTHOG_HOST"],
		["POSTHOG_ENVIRONMENT", "POSTHOG_ENVIRONMENT"],
	] as const) {
		const value = env[source];
		if (value !== undefined) vars[target] = value;
	}
	return vars;
}

function logTransientContainerRetry(
	observation: ContainerRetryObservation,
): void {
	if (observation.retryCount !== 1 && observation.retryCount % 30 !== 0) return;
	console.warn("Transient LixRay container failure; retrying", {
		workspaceId: observation.workspaceId,
		path: observation.operation,
		retryCount: observation.retryCount,
		retryDelayMs: observation.retryDelayMs,
		error: errorDetails(observation.error),
	});
}

function requiredEnv(value: string | undefined, name: string): string {
	if (!value) {
		throw new FileServiceError("upstream_error", `${name} is not configured.`);
	}
	return value;
}

function asRows(value: unknown): Array<Record<string, unknown>> {
	return Array.isArray(value)
		? value.filter(
				(row): row is Record<string, unknown> =>
					Boolean(row) && typeof row === "object",
			)
		: [];
}

function stringField(
	row: Record<string, unknown>,
	name: string,
): string | null {
	return typeof row[name] === "string" ? row[name] : null;
}

function errorDetails(caught: unknown): Record<string, unknown> {
	if (caught instanceof Error) {
		return { name: caught.name, message: caught.message, stack: caught.stack };
	}
	return caught && typeof caught === "object"
		? { ...(caught as Record<string, unknown>) }
		: { value: String(caught) };
}
", "export interface ContainerNamespace {
	getByName(name: string): ContainerStub;
}

export interface ContainerStub {
	startAndWaitForPorts?(options: {
		ports?: number | number[];
		cancellationOptions?: {
			abort?: AbortSignal;
			instanceGetTimeoutMS?: number;
			portReadyTimeoutMS?: number;
			waitInterval?: number;
		};
		startOptions: { envVars: Record<string, string> };
	}): Promise<unknown>;
	fetch(request: Request): Promise<Response>;
}

export type ContainerRetryDelay = (
	milliseconds: number,
	signal?: AbortSignal,
) => Promise<void>;

export interface ContainerRetryObservation {
	workspaceId: string;
	operation: string;
	retryCount: number;
	retryDelayMs: number;
	error: unknown;
}

export interface FetchContainerWithRetryOptions {
	namespace: ContainerNamespace;
	workspaceId: string;
	operation: string;
	envVars: Record<string, string>;
	createRequest: () => Request;
	requestReplay: "safe" | "unsafe";
	signal?: AbortSignal;
	retryDelay?: ContainerRetryDelay;
	retryRandom?: () => number;
	onRetry?: (observation: ContainerRetryObservation) => void;
}

const BASE_RETRY_DELAY_MS = 1_000;
const MAX_RETRY_DELAY_MS = 5_000;

const RETRYABLE_CONTAINER_ERROR_FRAGMENTS = [
	"container is not running",
	"there is no container instance",
	"too many containers per second",
	"container crashed",
	"container exited before",
	"failed to start container",
	"failed to verify port",
	"network connection lost",
	"container suddenly disconnected",
	"error proxying request to container",
	"container is not listening",
	"connection refused",
	"connection reset",
	"fetch failed",
	"timed out",
	"timeout",
	"internal error in durable object storage caused object to be reset",
	"durable object reset because its code was updated",
	"runtime signalled the container to exit due to a new version rollout",
];

const CONTAINER_NOT_READY_ERROR_FRAGMENTS = [
	"container is not running",
	"there is no container instance",
	"too many containers per second",
	"failed to start container",
	"failed to verify port",
	"container is not listening",
];

export async function fetchContainerWithRetry(
	options: FetchContainerWithRetryOptions,
): Promise<Response> {
	const retryDelay = options.retryDelay ?? delay;
	const retryRandom = options.retryRandom ?? Math.random;
	let retryCount = 0;

	for (;;) {
		throwIfAborted(options.signal);
		let container: ContainerStub;
		try {
			// A Durable Object reset creates a new object incarnation. Reacquiring the
			// stub on every attempt avoids retaining an RPC session from the reset one.
			container = options.namespace.getByName(options.workspaceId);
			const startup = container.startAndWaitForPorts?.({
				ports: 8080,
				startOptions: { envVars: options.envVars },
			});
			if (startup) await waitForPromiseWithAbort(startup, options.signal);
		} catch (caught) {
			throwIfAborted(options.signal);
			if (!isRetryableContainerError(caught)) throw caught;
			await waitBeforeContainerRetry(
				options,
				caught,
				++retryCount,
				retryDelay,
				retryRandom,
			);
			continue;
		}

		// Constructing the request happens after startup and outside a retry catch so
		// local serialization/programming failures are never mistaken for churn.
		const request = options.createRequest();
		let response: Response;
		try {
			response = await waitForPromiseWithAbort(
				container.fetch(request),
				options.signal,
			);
		} catch (caught) {
			throwIfAborted(options.signal);
			const canReplay =
				options.requestReplay === "safe" || isContainerNotReadyError(caught);
			if (!canReplay || !isRetryableContainerError(caught)) throw caught;
			await waitBeforeContainerRetry(
				options,
				caught,
				++retryCount,
				retryDelay,
				retryRandom,
			);
			continue;
		}

		const responseFailure = await retryableResponseFailure(
			response,
			options.requestReplay,
		);
		if (!responseFailure) return response;
		await cancelResponseBody(response);
		await waitBeforeContainerRetry(
			options,
			responseFailure,
			++retryCount,
			retryDelay,
			retryRandom,
		);
	}
}

export function isRetryableContainerError(caught: unknown): boolean {
	const message = errorMessageWithCauses(caught).toLowerCase();
	if (isDataCloneError(caught) || message.includes("abort")) return false;

	const exitCode = containerExitCode(message);
	if (exitCode !== null && exitCode !== 0) return false;
	if (hasErrorFlag(caught, "overloaded", true)) return false;
	if (hasErrorFlag(caught, "retryable", true)) return true;
	if (hasErrorFlag(caught, "retryable", false)) return false;

	return RETRYABLE_CONTAINER_ERROR_FRAGMENTS.some((fragment) =>
		message.includes(fragment),
	);
}

export function containerErrorDetails(
	caught: unknown,
): Record<string, unknown> {
	return containerErrorDetailsWithSeen(caught, new Set());
}

function containerErrorDetailsWithSeen(
	caught: unknown,
	seen: Set<unknown>,
): Record<string, unknown> {
	if (!isObject(caught)) return { value: String(caught) };
	if (seen.has(caught)) return { value: "Circular error cause" };
	seen.add(caught);

	const details: Record<string, unknown> = {};
	for (const property of [
		"name",
		"message",
		"stack",
		"retryable",
		"overloaded",
	] as const) {
		const value = errorProperty(caught, property);
		if (value !== undefined) details[property] = value;
	}
	const cause = errorProperty(caught, "cause");
	if (cause !== undefined) {
		details.cause = containerErrorDetailsWithSeen(cause, seen);
	}
	return Object.keys(details).length > 0
		? details
		: { value: "Unknown container error" };
}

export function containerRetryDelayMs(
	retryCount: number,
	random: () => number = Math.random,
): number {
	const exponent = Math.min(Math.max(retryCount - 1, 0), 3);
	const ceiling = Math.min(
		MAX_RETRY_DELAY_MS,
		BASE_RETRY_DELAY_MS * 2 ** exponent,
	);
	const floor = Math.ceil(ceiling / 2);
	const jitter = Math.min(Math.max(random(), 0), 1);
	return Math.round(floor + (ceiling - floor) * jitter);
}

export function logContainerRetry(
	observation: ContainerRetryObservation,
): void {
	if (observation.retryCount !== 1 && observation.retryCount % 30 !== 0) return;
	console.warn("Transient LixRay container failure; retrying", {
		workspaceId: observation.workspaceId,
		operation: observation.operation,
		retryCount: observation.retryCount,
		retryDelayMs: observation.retryDelayMs,
		error: containerErrorDetails(observation.error),
	});
}

async function retryableResponseFailure(
	response: Response,
	requestReplay: "safe" | "unsafe",
): Promise<Record<string, unknown> | null> {
	if (![429, 500, 502, 503, 504].includes(response.status)) return null;

	let body: unknown;
	try {
		body = await parseResponse(response.clone());
	} catch {
		return null;
	}
	const error = responseError(body, response.status);
	const canReplay =
		requestReplay === "safe"
			? isRetryableContainerError(error)
			: isContainerNotReadyError(error);
	return canReplay
		? { status: response.status, error: containerErrorDetails(error) }
		: null;
}

async function parseResponse(response: Response): Promise<unknown> {
	const contentType = response.headers.get("content-type") ?? "";
	return contentType.includes("application/json")
		? response.json()
		: response.text();
}

function responseError(body: unknown, status: number): unknown {
	if (body && typeof body === "object" && "error" in body) {
		const error = body.error;
		if (error !== undefined) return error;
	}
	if (body && typeof body === "object") return body;
	if (typeof body === "string" && body.trim()) return body.trim();
	return `Container request failed with status ${status}.`;
}

function errorMessageWithCauses(caught: unknown): string {
	const messages: Array<string> = [];
	const seen = new Set<unknown>();
	let current = caught;
	while (current !== undefined && current !== null && !seen.has(current)) {
		seen.add(current);
		if (isObject(current)) {
			const message = errorProperty(current, "message");
			messages.push(
				typeof message === "string" ? message : "Unknown container error",
			);
			current = errorProperty(current, "cause");
		} else if (
			typeof current === "string" ||
			typeof current === "number" ||
			typeof current === "boolean" ||
			typeof current === "bigint"
		) {
			messages.push(String(current));
			break;
		} else {
			messages.push("Unknown container error");
			break;
		}
	}
	return messages.join(" ");
}

function isContainerNotReadyError(caught: unknown): boolean {
	if (!isRetryableContainerError(caught)) return false;
	const message = errorMessageWithCauses(caught).toLowerCase();
	return CONTAINER_NOT_READY_ERROR_FRAGMENTS.some((fragment) =>
		message.includes(fragment),
	);
}

function isDataCloneError(caught: unknown): boolean {
	let current = caught;
	const seen = new Set<unknown>();
	while (isObject(current) && !seen.has(current)) {
		seen.add(current);
		if (errorProperty(current, "name") === "DataCloneError") return true;
		current = errorProperty(current, "cause");
	}
	return false;
}

function hasErrorFlag(
	caught: unknown,
	property: "retryable" | "overloaded",
	expected: boolean,
): boolean {
	let current = caught;
	const seen = new Set<unknown>();
	while (isObject(current) && !seen.has(current)) {
		seen.add(current);
		if (errorProperty(current, property) === expected) return true;
		current = errorProperty(current, "cause");
	}
	return false;
}

function isObject(value: unknown): value is object {
	return (
		(typeof value === "object" && value !== null) || typeof value === "function"
	);
}

function errorProperty(value: object, property: string): unknown {
	try {
		return Reflect.get(value, property);
	} catch {
		return undefined;
	}
}

function containerExitCode(message: string): number | null {
	const match = /exit code:\s*(-?\d+)/.exec(message);
	return match ? Number(match[1]) : null;
}

function throwIfAborted(signal: AbortSignal | null | undefined): void {
	if (!signal?.aborted) return;
	throw abortReason(signal);
}

async function cancelResponseBody(response: Response): Promise<void> {
	try {
		await response.body?.cancel();
	} catch {
		// The response is being discarded before the next attempt either way.
	}
}

async function waitBeforeContainerRetry(
	options: FetchContainerWithRetryOptions,
	error: unknown,
	retryCount: number,
	retryDelay: ContainerRetryDelay,
	retryRandom: () => number,
): Promise<void> {
	const retryDelayMs = containerRetryDelayMs(retryCount, retryRandom);
	options.onRetry?.({
		workspaceId: options.workspaceId,
		operation: options.operation,
		retryCount,
		retryDelayMs,
		error,
	});
	await retryDelay(retryDelayMs, options.signal);
}

function waitForPromiseWithAbort<T>(
	promise: Promise<T>,
	signal?: AbortSignal,
): Promise<T> {
	if (!signal) return promise;
	throwIfAborted(signal);
	return new Promise<T>((resolve, reject) => {
		let settled = false;
		const cleanup = () => signal.removeEventListener("abort", onAbort);
		const onFulfilled = (value: T) => {
			if (settled) return;
			settled = true;
			cleanup();
			resolve(value);
		};
		const onRejected = (error: unknown) => {
			if (settled) return;
			settled = true;
			cleanup();
			reject(
				error instanceof Error
					? error
					: new Error("Container operation failed.", { cause: error }),
			);
		};
		const onAbort = () => onRejected(abortReason(signal));
		signal.addEventListener("abort", onAbort, { once: true });
		promise.then(onFulfilled, onRejected);
	});
}

function abortReason(signal: AbortSignal): Error {
	return signal.reason instanceof Error
		? signal.reason
		: new DOMException("Container request was cancelled.", "AbortError");
}

function delay(milliseconds: number, signal?: AbortSignal): Promise<void> {
	return new Promise((resolve, reject) => {
		if (signal?.aborted) {
			reject(abortReason(signal));
			return;
		}
		const onAbort = () => {
			clearTimeout(timeout);
			reject(
				signal
					? abortReason(signal)
					: new DOMException("Container request was cancelled.", "AbortError"),
			);
		};
		const timeout = setTimeout(() => {
			signal?.removeEventListener("abort", onAbort);
			resolve();
		}, milliseconds);
		signal?.addEventListener("abort", onAbort, { once: true });
	});
}
", "import { Server } from "@modelcontextprotocol/sdk/server/index.js";
import {
	CallToolRequestSchema,
	ErrorCode,
	ListToolsRequestSchema,
	McpError,
	type ToolAnnotations,
} from "@modelcontextprotocol/sdk/types.js";
import { z } from "zod";
import { FileServiceError, LixFileService } from "./file-service.ts";
import { EXECUTE_TOOL_DESCRIPTION } from "./execute-schema.ts";
import {
	mcpSurfaceVersion,
	observeExecuteInput,
	observeExecuteOutput,
	type McpExecuteInputObservation,
	type McpExecuteOutputObservation,
} from "./tool-observation.ts";

export const MCP_PATH = "/mcp";
export const MCP_RESOURCE = "https://lixray.com";
export const MCP_PROTECTED_RESOURCE_PATH =
	"/.well-known/oauth-protected-resource";
export const MCP_DOCUMENTATION_PATH = "/docs/mcp";
export const MCP_PROTECTED_RESOURCE_URL = `${MCP_RESOURCE}${MCP_PROTECTED_RESOURCE_PATH}`;
export const MCP_SCOPES = ["openid", "email", "profile"] as const;

export type McpAuthMode = "oauth" | "none";

export interface McpToolCallObservation {
	toolName: string;
	outcome: "success" | "error";
	durationMs: number;
	surfaceVersion: string;
	errorCode?: string;
	workspaceId?: string;
	executeInput?: McpExecuteInputObservation;
	executeOutput?: McpExecuteOutputObservation;
}

export type McpToolCallObserver = (observation: McpToolCallObservation) => void;

export interface McpServerOptions {
	authMode?: McpAuthMode;
	onToolCall?: McpToolCallObserver;
}

type McpSecurityScheme =
	| { type: "oauth2"; scopes: Array<string> }
	| { type: "noauth" };

const oauthSecuritySchemes: Array<McpSecurityScheme> = [
	{ type: "oauth2", scopes: [...MCP_SCOPES] },
];

const uuid = z.uuid().describe("Workspace UUID");
const workspaceRef = z
	.string()
	.describe(
		"Exact workspace UUID, exact workspace slug, or exact @namespace/slug. Use the workspace UUID when available.",
	);
// Lix accepts non-UUID branch identifiers such as the built-in `global`
// branch. Keep the MCP contract as broad as the Lix client contract.
const branchId = z.string().min(1).describe("Lix branch ID");
const executeSqlText = z.string().trim().min(1);
const wireValue = z.discriminatedUnion("kind", [
	z.object({ kind: z.literal("null"), value: z.null().optional() }).strict(),
	z.object({ kind: z.literal("bool"), value: z.boolean() }).strict(),
	z.object({ kind: z.literal("int"), value: z.number().int().safe() }).strict(),
	z.object({ kind: z.literal("float"), value: z.number().finite() }).strict(),
	z.object({ kind: z.literal("text"), value: z.string() }).strict(),
	z.object({ kind: z.literal("blob"), base64: z.string() }).strict(),
	z.object({ kind: z.literal("json"), value: z.unknown() }).strict(),
]);
const executeStatement = z
	.object({
		sql: executeSqlText,
		params: z.array(wireValue).max(1000).optional().default([]),
	})
	.strict();
const workspaceSummaryOutput = z
	.object({
		id: uuid,
		name: z.string(),
		slug: z.string(),
		organization: z
			.object({ id: z.string(), name: z.string(), handle: z.string() })
			.strict(),
	})
	.strict();
const toolErrorOutput = z
	.object({
		error: z
			.object({
				code: z.string(),
				message: z.string(),
				details: z.record(z.string(), z.unknown()).optional(),
			})
			.strict(),
	})
	.strict();
const listWorkspacesOutput = z.union([
	z.object({ workspaces: z.array(workspaceSummaryOutput) }).strict(),
	toolErrorOutput,
]);
const activeBranchOutput = z.union([
	z.object({ branch_id: branchId }).strict(),
	toolErrorOutput,
]);
const executeStatementOutput = z
	.object({
		columns: z.array(z.string()),
		rows: z.array(z.array(wireValue)),
		rowsAffected: z.number().int().nonnegative(),
		notices: z.array(z.unknown()),
	})
	.strict();
const executeOutput = z.union([
	z.object({ results: z.array(executeStatementOutput) }).strict(),
	toolErrorOutput,
]);

interface ToolDefinition {
	descriptor: {
		name: string;
		title: string;
		description: string;
		inputSchema: Record<string, unknown>;
		outputSchema?: Record<string, unknown>;
		securitySchemes: Array<McpSecurityScheme>;
		annotations: ToolAnnotations;
		_meta: Record<string, unknown>;
	};
	schema: z.ZodType<Record<string, unknown>>;
	outputSchema?: z.ZodType<Record<string, unknown>>;
	call(args: Record<string, unknown>): Promise<unknown>;
}

export function createLixrayMcpServer(
	service: LixFileService,
	options: McpServerOptions = {},
): Server {
	const server = new Server(
		{ name: "LixRay", version: "0.1.0" },
		{
			capabilities: { tools: {} },
			instructions:
				"Use LixRay's execute tool for workspace inspection and changes. SQL and branch controls use the workspace's active Lix branch, just like the Lix client. Use active_branch_id to inspect it and switch_branch to change it. Query lix_branch with execute when you need the branch catalog. Freely make changes, as the user can review all changes in the UI. Never guess workspace or branch IDs.",
		},
	);
	const tools = buildTools(
		service,
		options.authMode === "none" ? [{ type: "noauth" }] : oauthSecuritySchemes,
	);
	const surfaceVersion = mcpSurfaceVersion(
		tools.map((tool) => tool.descriptor),
	);
	const observe = (
		startedAt: number,
		observation: Omit<McpToolCallObservation, "durationMs" | "surfaceVersion">,
	) =>
		observeToolCall(options.onToolCall, startedAt, {
			...observation,
			surfaceVersion,
		});

	server.setRequestHandler(ListToolsRequestSchema, () => ({
		tools: tools.map((tool) => tool.descriptor),
	}));
	server.setRequestHandler(CallToolRequestSchema, async (request) => {
		const startedAt = Date.now();
		const tool = tools.find(
			(candidate) => candidate.descriptor.name === request.params.name,
		);
		if (!tool) {
			observe(startedAt, {
				toolName: "unknown",
				outcome: "error",
				errorCode: "unknown_tool",
			});
			throw new McpError(
				ErrorCode.InvalidParams,
				`Unknown tool: ${request.params.name}`,
			);
		}
		const executeInput =
			tool.descriptor.name === "execute"
				? observeExecuteInput(request.params.arguments?.statements)
				: undefined;
		const parsed = tool.schema.safeParse(request.params.arguments ?? {});
		if (!parsed.success) {
			observe(startedAt, {
				toolName: tool.descriptor.name,
				outcome: "error",
				errorCode: "invalid_arguments",
				...(executeInput ? { executeInput } : {}),
			});
			return errorResult("invalid_arguments", z.prettifyError(parsed.error));
		}
		let workspaceId: string | undefined;
		try {
			const callArgs: Record<string, unknown> = { ...parsed.data };
			if (typeof parsed.data.workspace_ref === "string") {
				workspaceId = await service.resolveWorkspaceRef(
					parsed.data.workspace_ref,
				);
				callArgs.workspace_ref = workspaceId;
			}
			const rawStructuredContent = asStructuredContent(
				await tool.call(callArgs),
			);
			const parsedOutput = tool.outputSchema?.safeParse(rawStructuredContent);
			if (parsedOutput && !parsedOutput.success) {
				throw new Error(
					`${tool.descriptor.name} returned invalid structured output: ${z.prettifyError(parsedOutput.error)}`,
				);
			}
			const structuredContent = parsedOutput?.success
				? parsedOutput.data
				: rawStructuredContent;
			const executeOutput =
				tool.descriptor.name === "execute"
					? observeExecuteOutput(structuredContent)
					: undefined;
			observe(startedAt, {
				toolName: tool.descriptor.name,
				outcome: "success",
				...(workspaceId ? { workspaceId } : {}),
				...(executeInput ? { executeInput } : {}),
				...(executeOutput ? { executeOutput } : {}),
			});
			return {
				structuredContent,
				content: [
					{
						type: "text" as const,
						text: successSummary(tool.descriptor.name),
					},
				],
			};
		} catch (caught) {
			if (caught instanceof FileServiceError) {
				observe(startedAt, {
					toolName: tool.descriptor.name,
					outcome: "error",
					errorCode: caught.code,
					...(workspaceId ? { workspaceId } : {}),
					...(executeInput ? { executeInput } : {}),
				});
				return errorResult(caught.code, caught.message, caught.details);
			}
			observe(startedAt, {
				toolName: tool.descriptor.name,
				outcome: "error",
				errorCode: "internal_error",
				...(workspaceId ? { workspaceId } : {}),
				...(executeInput ? { executeInput } : {}),
			});
			console.error("LixRay MCP tool failed", {
				tool: tool.descriptor.name,
				error: errorDetails(caught),
			});
			return errorResult("internal_error", "The LixRay tool call failed.");
		}
	});

	return server;
}

function observeToolCall(
	observer: McpToolCallObserver | undefined,
	startedAt: number,
	observation: Omit<McpToolCallObservation, "durationMs">,
): void {
	if (!observer) return;
	try {
		observer({
			...observation,
			durationMs: Math.max(0, Date.now() - startedAt),
		});
	} catch (caught) {
		console.warn(
			"Failed to observe LixRay MCP tool call",
			errorDetails(caught),
		);
	}
}

export async function handleMcpTransport(
	request: Request,
	service: LixFileService,
	ctx: ExecutionContext,
	options: McpServerOptions = {},
): Promise<Response> {
	// Keep the Worker-only module out of Node's strip-types test loader. The
	// production Worker resolves this Cloudflare module when the MCP route runs.
	const { createMcpHandler } = await import("agents/mcp");
	return createMcpHandler(createLixrayMcpServer(service, options), {
		route: MCP_PATH,
		enableJsonResponse: true,
		sessionIdGenerator: undefined,
		corsOptions: {
			origin: "*",
			methods: "GET, POST, DELETE, OPTIONS",
			headers: "Authorization, Content-Type, MCP-Protocol-Version",
			exposeHeaders: "MCP-Session-Id, MCP-Protocol-Version",
		},
	})(request, undefined, ctx);
}

export interface McpDiscoveryOptions {
	protectedResourceUrl?: string;
	authorizationServer?: string;
	resourceDocumentationUrl?: string;
	endpointUrl?: string;
}

export function protectedResourceMetadataResponse(
	options: McpDiscoveryOptions = {},
): Response {
	if (!options.authorizationServer) {
		return new Response("MCP authorization is not configured\n", {
			status: 500,
		});
	}
	return Response.json(
		{
			resource: MCP_RESOURCE,
			authorization_servers: [options.authorizationServer],
			scopes_supported: [...MCP_SCOPES],
			resource_documentation:
				options.resourceDocumentationUrl ??
				`${MCP_RESOURCE}${MCP_DOCUMENTATION_PATH}`,
		},
		{
			headers: {
				"access-control-allow-origin": "*",
				"cache-control": "public, max-age=300",
			},
		},
	);
}

export function mcpDocumentationResponse(
	options: McpDiscoveryOptions = {},
): Response {
	return new Response(
		[
			"LixRay MCP",
			"",
			`Endpoint: ${options.endpointUrl ?? `${MCP_RESOURCE}${MCP_PATH}`}`,
			"Authentication: Supabase OAuth 2.1 with PKCE and dynamic client registration.",
			"",
			"Your LixRay browser session and your MCP client authorization are separate. Being signed in at lixray.com does not mean that Codex or another MCP client has a usable access and refresh token.",
			"",
			"Connection check:",
			"1. Confirm this endpoint is registered exactly once for the environment you intend to use.",
			"2. Revoke or log out the MCP connection, then authorize it again.",
			"3. Verify that initialize, tools/list, and list_workspaces all succeed in a fresh client process.",
			"",
			"If the client reports that no refresh token is available, remove the connection's saved authorization and reconnect. If it recurs, report the client version, server URL, and time of the attempt; do not include access or refresh tokens.",
			"",
			"The server exposes list_workspaces, active_branch_id, switch_branch, and raw Lix SQL execute. SQL and branch controls use the workspace's active Lix branch, matching the Lix client. Use active_branch_id to inspect it, switch_branch to change it, and SQL against lix_branch to discover branches. Execute accepts an ordered batch of statements with $n or ? parameters. Lix executes the batch atomically and returns one ordered result per statement.",
		].join("\n"),
		{
			headers: {
				"content-type": "text/plain; charset=utf-8",
				"cache-control": "public, max-age=300",
			},
		},
	);
}

export function mcpUnauthorizedResponse(
	error = "invalid_token",
	description = "Sign in to LixRay to continue.",
	protectedResourceUrl = MCP_PROTECTED_RESOURCE_URL,
): Response {
	const challenge = mcpAuthenticateChallenge(
		error,
		description,
		protectedResourceUrl,
	);
	return Response.json(
		{
			error: "unauthorized",
			error_description: description,
			_meta: { "mcp/www_authenticate": [challenge] },
		},
		{
			status: 401,
			headers: {
				"access-control-allow-origin": "*",
				"WWW-Authenticate": challenge,
			},
		},
	);
}

export function mcpAuthenticateChallenge(
	error = "invalid_token",
	description = "Sign in to LixRay to continue.",
	protectedResourceUrl = MCP_PROTECTED_RESOURCE_URL,
): string {
	return `Bearer resource_metadata="${protectedResourceUrl}", scope="${MCP_SCOPES.join(" ")}", error="${error}", error_description="${description.replaceAll('"', "'")}"`;
}

function buildTools(
	service: LixFileService,
	securitySchemes: Array<McpSecurityScheme>,
): Array<ToolDefinition> {
	const tool = <T extends z.ZodType<Record<string, unknown>>>(
		name: string,
		title: string,
		description: string,
		schema: T,
		annotations: ToolAnnotations,
		call: (args: z.output<T>) => Promise<unknown>,
		outputSchema?: z.ZodType<Record<string, unknown>>,
	) =>
		createTool(
			name,
			title,
			description,
			schema,
			annotations,
			securitySchemes,
			call,
			outputSchema,
		);
	return [
		tool(
			"list_workspaces",
			"List workspaces",
			"List the LixRay workspaces the signed-in user can access.",
			z.object({}).strict(),
			readAnnotations(),
			async () => ({ workspaces: await service.listWorkspaces() }),
			listWorkspacesOutput,
		),
		tool(
			"active_branch_id",
			"Get active branch ID",
			"Return the workspace's active Lix branch ID.",
			z.object({ workspace_ref: workspaceRef }).strict(),
			readAnnotations(),
			async ({ workspace_ref }) => ({
				branch_id: await service.activeBranchId(String(workspace_ref)),
			}),
			activeBranchOutput,
		),
		tool(
			"switch_branch",
			"Switch active branch",
			"Switch the workspace's active Lix branch. This shared workspace state affects subsequent SQL operations.",
			z
				.object({
					workspace_ref: workspaceRef,
					branch_id: branchId,
				})
				.strict(),
			writeAnnotations(false, false),
			async ({ workspace_ref, branch_id }) => ({
				branch_id: (
					await service.switchBranch(String(workspace_ref), String(branch_id))
				).branchId,
			}),
			activeBranchOutput,
		),
		tool(
			"execute",
			"Execute raw Lix SQL",
			EXECUTE_TOOL_DESCRIPTION,
			z
				.object({
					workspace_ref: workspaceRef,
					statements: z.array(executeStatement).min(1).max(100),
				})
				.strict(),
			writeAnnotations(false, false),
			async ({ workspace_ref, statements }) =>
				service.executeSql(
					String(workspace_ref),
					statements.map((statement) => ({
						sql: statement.sql,
						params: statement.params,
					})),
				),
			executeOutput,
		),
	];
}

function createTool<T extends z.ZodType<Record<string, unknown>>>(
	name: string,
	title: string,
	description: string,
	schema: T,
	annotations: ToolAnnotations,
	securitySchemes: Array<McpSecurityScheme>,
	call: (args: z.output<T>) => Promise<unknown>,
	outputSchema?: z.ZodType<Record<string, unknown>>,
): ToolDefinition {
	return {
		descriptor: {
			name,
			title,
			description,
			inputSchema: mcpJsonSchema(schema, "input"),
			...(outputSchema
				? {
						outputSchema: {
							...mcpJsonSchema(outputSchema, "output"),
							type: "object" as const,
						},
					}
				: {}),
			securitySchemes: securitySchemes.map(cloneSecurityScheme),
			annotations,
			_meta: {
				securitySchemes: securitySchemes.map(cloneSecurityScheme),
			},
		},
		schema,
		...(outputSchema ? { outputSchema } : {}),
		call: (args) => call(args as z.output<T>),
	};
}

function mcpJsonSchema(
	schema: z.ZodType,
	io: "input" | "output",
): Record<string, unknown> {
	const jsonSchema = z.toJSONSchema(schema, { io }) as Record<string, unknown>;
	removeUuidPatterns(jsonSchema);
	return jsonSchema;
}

function removeUuidPatterns(value: unknown): void {
	if (!value || typeof value !== "object") return;
	if (Array.isArray(value)) {
		for (const item of value) removeUuidPatterns(item);
		return;
	}
	const object = value as Record<string, unknown>;
	if (object.format === "uuid") delete object.pattern;
	for (const child of Object.values(object)) removeUuidPatterns(child);
}

function cloneSecurityScheme(scheme: McpSecurityScheme): McpSecurityScheme {
	return scheme.type === "oauth2"
		? { ...scheme, scopes: [...scheme.scopes] }
		: { ...scheme };
}

function readAnnotations(): ToolAnnotations {
	return {
		readOnlyHint: true,
		destructiveHint: false,
		openWorldHint: false,
		idempotentHint: true,
	};
}

function writeAnnotations(
	destructiveHint: boolean,
	idempotentHint: boolean,
): ToolAnnotations {
	return {
		readOnlyHint: false,
		destructiveHint,
		openWorldHint: false,
		idempotentHint,
	};
}

function errorResult(
	code: string,
	message: string,
	details?: Record<string, unknown>,
) {
	return {
		structuredContent: { error: { code, message, details } },
		content: [{ type: "text" as const, text: `${code}: ${message}` }],
		isError: true,
	};
}

function asStructuredContent(value: unknown): Record<string, unknown> {
