void test("failed remote review persistence survives tab loss and retries idempotently", async () => {
	const durableStorage = new MemoryStorage();
	const remoteReviewIds = new Set<string>();
	let upsertAttempts = 0;
	const client = fakeReviewClient({
		load: () => [...remoteReviewIds],
		upsert: (row) => {
			upsertAttempts += 1;
			if (upsertAttempts === 1) return new Error("temporarily unavailable");
			remoteReviewIds.add(row.review_id);
			return null;
		},
	});
	const reviews = createWorkspaceReviewStatusStore({
		client,
		userId: USER,
		workspaceId: WORKSPACE,
		durableStorage,
	});

	await reviews.resolve({
		branchId: DRAFT,
		reviewId: "review-outbox",
		fileId: "file-outbox",
		outcome: "rejected",
	});
	assert.equal(upsertAttempts, 1);
	assert.deepEqual(
		await createWorkspaceReviewStatusStore({
			client: null,
			userId: USER,
			workspaceId: WORKSPACE,
			storage: durableStorage,
		}).loadResolvedReviewIds(DRAFT),
		["review-outbox"],
		"the local acknowledgement is durable before the remote write succeeds",
	);

	const freshTab = createWorkspaceReviewStatusStore({
		client,
		userId: USER,
		workspaceId: WORKSPACE,
		durableStorage,
	});
	assert.deepEqual(await freshTab.loadResolvedReviewIds(DRAFT), [
		"review-outbox",
	]);
	assert.equal(upsertAttempts, 2);
	assert.deepEqual(await freshTab.loadResolvedReviewIds(DRAFT), [
		"review-outbox",
	]);
	assert.equal(
		upsertAttempts,
		2,
		"a flushed outbox entry is not retried again",
	);
});

void test("workspace sessions use unified remote Lix with shared branch state and one observation stream", async (t) => {
	const executeBranches: string[] = [];
	const createBodies: unknown[] = [];
	const requestPaths: string[] = [];
	let activeBranchId = MAIN;
	let observeOpenCount = 0;
	let observationSequence = 0;
	let observationController:
		| ReadableStreamDefaultController<Uint8Array>
		| undefined;
	let observationSubscriptionId: string | undefined;
	const emitObservation = () => {
		if (!observationController || !observationSubscriptionId) return;
		const frame = `event: next\ndata: ${JSON.stringify({
			subscriptionId: observationSubscriptionId,
			sequence: observationSequence++,
			mutationSequence: observationSequence,
			result: {
				columns: ["branch"],
				rows: [[{ kind: "text", value: activeBranchId }]],
				rowsAffected: 0,
				notices: [],
			},
		})}\n\n`;
		observationController.enqueue(new TextEncoder().encode(frame));
	};
	const fetch = async (input: RequestInfo | URL, init?: RequestInit) => {
		const request =
			input instanceof Request
				? input
				: new Request(new URL(input, "https://lixray.test"), init);
		const pathname = new URL(request.url).pathname;
		requestPaths.push(pathname);
		if (pathname.endsWith("/lix/v1/")) {
			return Response.json({
				protocolVersion: 1,
				activeBranchId,
				sessionId: "workspace-session",
			});
		}
		if (pathname.endsWith("/lix/v1/session") && request.method === "DELETE") {
			return new Response(null, { status: 204 });
		}
		const body: Record<string, unknown> = request.body
			? await request.clone().json()
			: {};
		if (pathname.endsWith("/branch/switch")) {
			const branchId = body.branchId;
			if (branchId === "invalid-branch") {
				return Response.json(
					{
						error: {
							code: "LIX_BRANCH_NOT_FOUND",
							message: "Branch not found",
						},
					},
					{ status: 404 },
				);
			}
			activeBranchId = String(branchId);
			emitObservation();
			return Response.json({ branchId });
		}
		if (pathname.endsWith("/branch/create")) {
			createBodies.push(body);
			return Response.json({
				id: CREATED,
				name: "Created",
				hidden: false,
				commitId: "created-commit",
			});
		}
		if (pathname.endsWith("/execute")) {
			executeBranches.push(activeBranchId);
			return Response.json({
				columns: [],
				rows: [],
				rowsAffected: 0,
				notices: [],
			});
		}
		if (pathname.endsWith("/observe/multiplex")) {
			observeOpenCount += 1;
			const subscriptions = body.subscriptions as Array<{ id: string }>;
			observationSubscriptionId = subscriptions[0]?.id;
			const signal = request.signal;
			return new Response(
				new ReadableStream<Uint8Array>({
					start(controller) {
						observationController = controller;
						emitObservation();
						if (signal?.aborted) controller.close();
						else {
							signal?.addEventListener(
								"abort",
								() => {
									observationController = undefined;
									controller.close();
								},
								{ once: true },
							);
						}
					},
				}),
				{ headers: { "content-type": "text/event-stream" } },
			);
		}
		return new Response("Not found", { status: 404 });
	};
	const session = await openWorkspaceLixSession({
		namespace: "acme",
		workspaceSlug: "launch-q3",
		origin: "https://lixray.test",
		getAccessToken: async () => "token",
		initialBranchId: "invalid-branch",
		fetch,
	});
	t.after(() => session.close());
	assert.equal(session.activeBranchSnapshot(), MAIN);
	await session.lix.execute("SELECT 1");
	const events = session.lix.observe("SELECT branch");
	t.after(() => events.close());
	assert.equal((await events.next())?.result.rows[0]?.get("branch"), MAIN);
	await session.switchBranch(DRAFT);
	assert.equal((await events.next())?.result.rows[0]?.get("branch"), DRAFT);
	await session.lix.execute("SELECT 2");
	assert.equal(await session.createBranch("Created"), CREATED);
	assert.equal(session.activeBranchSnapshot(), CREATED);
	assert.equal((await events.next())?.result.rows[0]?.get("branch"), CREATED);
	assert.deepEqual(executeBranches, [MAIN, DRAFT]);
	assert.deepEqual(createBodies, [{ name: "Created" }]);
	assert.equal(observeOpenCount, 1);
	assert.equal(requestPaths[0], "/@acme/launch-q3/lix/v1/");
	assert.ok(requestPaths.includes("/@acme/launch-q3/lix/v1/observe/multiplex"));
});

type RemoteReviewRow = {
	review_id: string;
};

function fakeReviewClient(args: {
	load: () => string[];
	upsert: (row: RemoteReviewRow) => Error | null;
}): LixraySupabaseClient {
	return {
		from: () => new FakeReviewQuery(args),
	} as unknown as LixraySupabaseClient;
}

class FakeReviewQuery {
	readonly #args: {
		load: () => string[];
		upsert: (row: RemoteReviewRow) => Error | null;
	};

	constructor(args: {
		load: () => string[];
		upsert: (row: RemoteReviewRow) => Error | null;
	}) {
		this.#args = args;
	}

	select(): this {
		return this;
	}

	eq(): this {
		return this;
	}

	async upsert(row: RemoteReviewRow): Promise<{ error: Error | null }> {
		return { error: this.#args.upsert(row) };
	}

	then<TResult1 = { data: RemoteReviewRow[]; error: null }, TResult2 = never>(
		onfulfilled?:
			| ((value: {
					data: RemoteReviewRow[];
					error: null;
			  }) => TResult1 | PromiseLike<TResult1>)
			| null,
		onrejected?: ((reason: unknown) => TResult2 | PromiseLike<TResult2>) | null,
	): Promise<TResult1 | TResult2> {
		return Promise.resolve({
			data: this.#args.load().map((review_id) => ({ review_id })),
			error: null,
		}).then(onfulfilled, onrejected);
	}
}

class MemoryStorage implements Storage {
	readonly #values = new Map<string, string>();

	get length(): number {
		return this.#values.size;
	}

	clear(): void {
		this.#values.clear();
	}

	getItem(key: string): string | null {
		return this.#values.get(key) ?? null;
	}

	key(index: number): string | null {
		return [...this.#values.keys()][index] ?? null;
	}

	removeItem(key: string): void {
		this.#values.delete(key);
	}

	setItem(key: string, value: string): void {
		this.#values.set(key, value);
	}
}
", "import {
	coerceAtelierSessionUiState,
	coerceAtelierUserPreferences,
	type AtelierBranchSession,
	type AtelierPreferencesStore,
	type AtelierReviewStatusStore,
	type AtelierReviewResolution,
	type AtelierSessionStateStore,
	type AtelierSessionUiState,
	type AtelierUserPreferencesV1,
} from "@opral/atelier/state-adapters";
import type { LixraySupabaseClient } from "./supabase";
import type { WorkspaceLixSession } from "./workspace-lix-session";

const SESSION_STATE_VERSION = 1;
const PREFERENCES_STATE_VERSION = 1;
const REVIEW_STATE_VERSION = 1;

export function createWorkspaceSessionStateStore(args: {
	readonly userId: string;
	readonly workspaceId: string;
	readonly storage?: Storage;
}): AtelierSessionStateStore {
	const storage = args.storage ?? window.localStorage;
	const legacyStorage = args.storage ? null : window.sessionStorage;
	const key = namespacedAtelierStateKey("shell", SESSION_STATE_VERSION, args);
	const value = readStoredJson(storage, key);
	let snapshot: AtelierSessionUiState | null = value
		? coerceAtelierSessionUiState(value)
		: null;
	if (!snapshot && legacyStorage) {
		const legacyValue = readStoredJson(legacyStorage, key);
		if (legacyValue) {
			snapshot = coerceAtelierSessionUiState(legacyValue);
			storage.setItem(key, JSON.stringify(snapshot));
		}
	}
	legacyStorage?.removeItem(key);
	const listeners = new Set<() => void>();
	return {
		getSnapshot: () => snapshot,
		setSnapshot: (nextValue: AtelierSessionUiState) => {
			const next = coerceAtelierSessionUiState(nextValue);
			if (JSON.stringify(snapshot) === JSON.stringify(next)) return;
			snapshot = next;
			storage.setItem(key, JSON.stringify(next));
			for (const listener of [...listeners]) listener();
		},
		subscribe: (listener: () => void) => {
			listeners.add(listener);
			return () => listeners.delete(listener);
		},
	};
}

export function createWorkspaceBranchSession(args: {
	readonly session: WorkspaceLixSession;
	readonly onSwitch: (
		branchId: string,
		context?: { readonly failedBranchId?: string },
	) => Promise<void> | void;
}): AtelierBranchSession {
	let latestSelection = 0;
	let pendingSelection = Promise.resolve();
	const select = <T>(
		operation: () => Promise<T>,
		branchId: (value: T) => string,
		failedBranchId?: string,
	): Promise<T> => {
		const selection = ++latestSelection;
		const result = pendingSelection.then(async () => {
			let value: T;
			try {
				value = await operation();
			} catch (error) {
				if (selection === latestSelection) {
					try {
						await args.onSwitch(
							args.session.activeBranchSnapshot(),
							failedBranchId ? { failedBranchId } : undefined,
						);
					} catch {
						// Preserve the branch operation error. A later selection can retry
						// navigation without obscuring why this selection failed.
					}
				}
				throw error;
			}
			if (selection === latestSelection) {
				await args.onSwitch(branchId(value));
			}
			return value;
		});
		pendingSelection = result.then(
			() => undefined,
			() => undefined,
		);
		return result;
	};
	return {
		getSnapshot: args.session.activeBranchSnapshot.bind(args.session),
		subscribe: args.session.subscribeActiveBranch.bind(args.session),
		createBranch: async (name: string) => {
			return select(
				() => args.session.createBranch(name),
				(branchId) => branchId,
			);
		},
		switchBranch: async (branchId: string) => {
			await select(
				() =>
					args.session.activeBranchSnapshot() === branchId
						? Promise.resolve(branchId)
						: args.session.switchBranch(branchId),
				(selectedBranchId) => selectedBranchId,
				branchId,
			);
		},
	};
}

export function createWorkspacePreferencesStore(args: {
	readonly client: LixraySupabaseClient | null;
	readonly userId: string;
	readonly workspaceId: string;
	readonly storage?: Storage;
}): AtelierPreferencesStore {
	const client = args.client;
	if (!client) {
		const storage = args.storage ?? window.sessionStorage;
		const key = namespacedAtelierStateKey(
			"preferences",
			PREFERENCES_STATE_VERSION,
			args,
		);
		return {
			load: () => {
				const value = readStoredJson(storage, key);
				return Promise.resolve(
					value ? coerceAtelierUserPreferences(value) : null,
				);
			},
			save: (value: AtelierUserPreferencesV1) => {
				storage.setItem(
					key,
					JSON.stringify(coerceAtelierUserPreferences(value)),
				);
				return Promise.resolve();
			},
		};
	}
	return {
		load: async () => {
			const { data, error } = await client
				.from("user_workspace_preferences")
				.select("atelier_layout")
				.eq("user_id", args.userId)
				.eq("workspace_id", args.workspaceId)
				.maybeSingle();
			if (error) throw error;
			return data?.atelier_layout
				? coerceAtelierUserPreferences(data.atelier_layout)
				: null;
		},
		save: async (value: AtelierUserPreferencesV1) => {
			const preferences = coerceAtelierUserPreferences(value);
			const { error } = await client.from("user_workspace_preferences").upsert(
				{
					user_id: args.userId,
					workspace_id: args.workspaceId,
					atelier_layout: preferences,
					updated_at: new Date().toISOString(),
				},
				{ onConflict: "user_id,workspace_id" },
			);
			if (error) throw error;
		},
	};
}

export function createWorkspaceReviewStatusStore(args: {
	readonly client: LixraySupabaseClient | null;
	readonly userId: string;
	readonly workspaceId: string;
	readonly storage?: Storage;
	readonly durableStorage?: Storage;
}): AtelierReviewStatusStore {
	const client = args.client;
	const storage =
		args.storage ??
		(client
			? (args.durableStorage ?? window.localStorage)
			: window.sessionStorage);
	const key = namespacedAtelierStateKey("reviews", REVIEW_STATE_VERSION, args);
	const localReviewIds = (branchId: string) =>
		readReviewState(storage, key)
			.resolutions.filter((review) => review.branchId === branchId)
			.map((review) => review.reviewId);
	const persistRemote = async (review: AtelierReviewResolution) => {
		if (!client) return;
		const { error } = await client
			.from("user_workspace_review_resolutions")
			.upsert(
				{
					user_id: args.userId,
					workspace_id: args.workspaceId,
					branch_id: review.branchId,
					review_id: review.reviewId,
					file_id: review.fileId,
					outcome: review.outcome,
					resolved_at: new Date().toISOString(),
				},
				{
					onConflict: "user_id,workspace_id,branch_id,review_id,file_id",
				},
			);
		if (error) throw error;
	};
	const flushPending = async () => {
		if (!client) return;
		const state = readReviewState(storage, key);
		for (const pendingKey of [...state.pending]) {
			const review = state.resolutions.find(
				(candidate) => reviewResolutionKey(candidate) === pendingKey,
			);
			if (!review) {
				state.pending = state.pending.filter((value) => value !== pendingKey);
				writeReviewState(storage, key, state);
				continue;
			}
			try {
				await persistRemote(review);
				const latest = readReviewState(storage, key);
				latest.pending = latest.pending.filter((value) => value !== pendingKey);
				writeReviewState(storage, key, latest);
			} catch {
				// The local acknowledgement is authoritative for this account in this
				// browser. Keep the idempotent upsert in the durable outbox for a later
				// load/retry.
			}
		}
	};
	return {
		loadResolvedReviewIds: async (branchId: string) => {
			await flushPending();
			const localIds = localReviewIds(branchId);
			if (!client) return [...new Set(localIds)];
			const { data, error } = await client
				.from("user_workspace_review_resolutions")
				.select("review_id")
				.eq("user_id", args.userId)
				.eq("workspace_id", args.workspaceId)
				.eq("branch_id", branchId);
			if (error) {
				if (localIds.length > 0) return [...new Set(localIds)];
				throw error;
			}
			return [...new Set([...localIds, ...data.map((row) => row.review_id)])];
		},
		resolve: async (review: AtelierReviewResolution) => {
			const state = readReviewState(storage, key);
			const reviewKey = reviewResolutionKey(review);
			state.resolutions = [
				...state.resolutions.filter(
					(candidate) => reviewResolutionKey(candidate) !== reviewKey,
				),
				review,
			];
			state.pending = [...new Set([...state.pending, reviewKey])];
			writeReviewState(storage, key, state);
			await flushPending();
		},
	};
}

type StoredReviewState = {
	resolutions: AtelierReviewResolution[];
	pending: string[];
};

function readReviewState(storage: Storage, key: string): StoredReviewState {
	const value = readStoredJson(storage, key);
	if (!value || typeof value !== "object" || Array.isArray(value)) {
		return { resolutions: [], pending: [] };
	}
	const candidate = value as { resolutions?: unknown; pending?: unknown };
	return {
		resolutions: Array.isArray(candidate.resolutions)
			? candidate.resolutions.filter(isReviewResolution)
			: [],
		pending: Array.isArray(candidate.pending)
			? candidate.pending.filter(
					(pendingKey): pendingKey is string => typeof pendingKey === "string",
				)
			: [],
	};
}

function writeReviewState(
	storage: Storage,
	key: string,
	state: StoredReviewState,
): void {
	storage.setItem(key, JSON.stringify(state));
}

function isReviewResolution(value: unknown): value is AtelierReviewResolution {
	if (!value || typeof value !== "object" || Array.isArray(value)) return false;
	const review = value as Partial<AtelierReviewResolution>;
	return (
		typeof review.branchId === "string" &&
		typeof review.reviewId === "string" &&
		typeof review.fileId === "string" &&
		(review.outcome === "accepted" ||
			review.outcome === "rejected" ||
			review.outcome === "resolved")
	);
}

function reviewResolutionKey(review: AtelierReviewResolution): string {
	return JSON.stringify([review.branchId, review.reviewId, review.fileId]);
}

function namespacedAtelierStateKey(
	family: "shell" | "preferences" | "reviews",
	version: number,
	args: { readonly userId: string; readonly workspaceId: string },
): string {
	return `lixray.atelier.${family}.v${version}:${args.userId}:${args.workspaceId}`;
}

function readStoredJson(storage: Storage, key: string): unknown {
	const encoded = storage.getItem(key);
	if (!encoded) return null;
	try {
		return JSON.parse(encoded) as unknown;
	} catch {
		storage.removeItem(key);
		return null;
	}
}
", "import { openLix, type Lix, type RemoteLixFetch } from "@lix-js/sdk/remote";

type TokenProvider = () => Promise<string | null>;

export interface OpenWorkspaceLixSessionOptions {
	namespace: string;
	workspaceSlug: string;
	getAccessToken: TokenProvider;
	/**
	 * Opens the session without an Authorization header when no access token
	 * is available. The worker only serves such requests through its public,
	 * read-only workspace transport.
	 */
	allowAnonymous?: boolean;
	initialBranchId?: string | null;
	origin?: string | URL;
	fetch?: RemoteLixFetch;
}

export interface WorkspaceLixSession {
	readonly lix: Lix;
	activeBranchSnapshot(): string;
	defaultBranchSnapshot(): string;
	subscribeActiveBranch(listener: () => void): () => void;
	createBranch(name: string): Promise<string>;
	switchBranch(branchId: string): Promise<string>;
	close(): Promise<void>;
}

export async function openWorkspaceLixSession(
	options: OpenWorkspaceLixSessionOptions,
): Promise<WorkspaceLixSession> {
	const lix = await openLix({
		server: {
			mode: "remote",
			url: workspaceUrl(options),
			headers: async (): Promise<Record<string, string>> => {
				const token = await options.getAccessToken();
				if (token) return { Authorization: `Bearer ${token}` };
				if (options.allowAnonymous) return {};
				throw new Error("A workspace access token is required.");
			},
			...(options.fetch ? { fetch: options.fetch } : {}),
		},
	});

	try {
		const defaultBranchId = await lix.activeBranchId();
		const session = new RemoteWorkspaceLixSession(lix, defaultBranchId);
		if (
			options.initialBranchId &&
			options.initialBranchId !== defaultBranchId
		) {
			try {
				await session.switchBranch(options.initialBranchId);
			} catch (error) {
				if (!isBranchNotFoundError(error)) throw error;
			}
		}
		return session;
	} catch (error) {
		await lix.close().catch(() => undefined);
		throw error;
	}
}

class RemoteWorkspaceLixSession implements WorkspaceLixSession {
	readonly lix: Lix;
	readonly #listeners = new Set<() => void>();
	readonly #defaultBranchId: string;
	#activeBranchId: string;
	#closed = false;

	constructor(lix: Lix, defaultBranchId: string) {
		this.lix = lix;
		this.#defaultBranchId = defaultBranchId;
		this.#activeBranchId = defaultBranchId;
	}

	activeBranchSnapshot(): string {
		this.#assertOpen();
		return this.#activeBranchId;
	}

	defaultBranchSnapshot(): string {
		this.#assertOpen();
		return this.#defaultBranchId;
	}

	subscribeActiveBranch(listener: () => void): () => void {
		this.#assertOpen();
		this.#listeners.add(listener);
		return () => this.#listeners.delete(listener);
	}

	async createBranch(name: string): Promise<string> {
		this.#assertOpen();
		const branch = await this.lix.createBranch({ name });
		await this.switchBranch(branch.id);
		return branch.id;
	}

	async switchBranch(branchId: string): Promise<string> {
		this.#assertOpen();
		if (branchId === this.#activeBranchId) return branchId;
		const switched = await this.lix.switchBranch({ branchId });
		this.#activeBranchId = switched.branchId;
		for (const listener of [...this.#listeners]) listener();
		return switched.branchId;
	}

	async close(): Promise<void> {
		if (this.#closed) return;
		this.#closed = true;
		this.#listeners.clear();
		await this.lix.close();
	}

	#assertOpen(): void {
		if (this.#closed) throw new Error("The workspace Lix session is closed.");
	}
}

function workspaceUrl(options: OpenWorkspaceLixSessionOptions): URL {
	const origin = options.origin ?? globalThis.location?.origin;
	if (!origin) throw new Error("A workspace server origin is required.");
	return new URL(
		`/@${encodeURIComponent(options.namespace)}/${encodeURIComponent(options.workspaceSlug)}`,
		origin,
	);
}

function isBranchNotFoundError(
	error: unknown,
): error is Error & { code: "LIX_BRANCH_NOT_FOUND" } {
	return (
		error instanceof Error &&
		"code" in error &&
		error.code === "LIX_BRANCH_NOT_FOUND"
	);
}
