import test from "node:test";
import {
	WorkerLixRuntimeClient,
	type WorkerLixRuntimeEnv,
} from "./runtime-client.ts";
import { FileServiceError } from "./file-service.ts";

const WORKSPACE_ID = "11111111-1111-4111-8111-111111111111";

async function branchProtocolResponse(request: Request): Promise<Response> {
	const pathname = testProtocolPath(request);
	if (pathname === "/lix/v1/") {
		return Response.json({
			protocolVersion: 1,
			activeBranchId: "main",
			sessionId: "runtime-client-session",
		});
	}
	if (pathname === "/lix/v1/session" && request.method === "DELETE") {
		return new Response(null, { status: 204 });
	}
	if (pathname === "/lix/v1/execute") {
		return Response.json({
			columns: ["id", "name", "hidden", "commit_id"],
			rows: [
				[
					{ kind: "text", value: "main" },
					{ kind: "text", value: "main" },
					{ kind: "bool", value: false },
					{ kind: "text", value: "commit-1" },
				],
			],
			rowsAffected: 0,
			notices: [],
		});
	}
	if (pathname === "/lix/v1/branch/switch") {
		const body: { branchId: string } = await request.json();
		return Response.json({ branchId: body.branchId });
	}
	return new Response("Not found", { status: 404 });
}

function testProtocolPath(request: Request): string {
	return new URL(request.url).pathname.replace(/^\/workspaces\/[^/]+/, "");
}

void test("container calls reauthorize every time and never forward the OAuth token", async () => {
	let authorizationChecks = 0;
	let starts = 0;
	const containerEnvironments: Array<Record<string, string>> = [];
	const requests: Array<Request> = [];
	const client = new WorkerLixRuntimeClient(
		env({
			extra: {
				POSTHOG_PROJECT_TOKEN: "project-token",
				POSTHOG_HOST: "https://posthog.example",
				POSTHOG_ENVIRONMENT: "production",
			},
			getByName: (name) => {
				assert.equal(name, WORKSPACE_ID);
				return {
					startAndWaitForPorts: async (options) => {
						starts += 1;
						containerEnvironments.push(options.startOptions.envVars);
					},
					fetch: async (request) => {
						requests.push(request);
						return branchProtocolResponse(request);
					},
				};
			},
		}),
		{ userId: "user-1", token: "secret-oauth-token" },
		async (workspaceId, user) => {
			authorizationChecks += 1;
			assert.equal(workspaceId, WORKSPACE_ID);
			assert.equal(user.token, "secret-oauth-token");
			return null;
		},
	);

	await client.execute(WORKSPACE_ID, { sql: "SELECT 1" });
	await client.execute(WORKSPACE_ID, { sql: "SELECT 2" });
	assert.equal(authorizationChecks, 3);
	assert.equal(starts, 3);
	assert.deepEqual(containerEnvironments[0], {
		POSTHOG_PROJECT_TOKEN: "project-token",
		POSTHOG_HOST: "https://posthog.example",
		POSTHOG_ENVIRONMENT: "production",
	});
	assert.equal(requests.length, 3);
	assert.deepEqual(
		requests.map((request) => new URL(request.url).pathname),
		[
			`/workspaces/${WORKSPACE_ID}/lix/v1/`,
			`/workspaces/${WORKSPACE_ID}/lix/v1/execute`,
			`/workspaces/${WORKSPACE_ID}/lix/v1/execute`,
		],
	);
	for (const request of requests) {
		assert.equal(request.headers.get("authorization"), null);
		assert.equal(
			(await request.clone().text()).includes("secret-oauth-token"),
			false,
		);
	}
});

void test("active-branch lookup reauthorizes each protocol request without listing branches", async () => {
	let authorizationChecks = 0;
	const requests: Array<Request> = [];
	const client = new WorkerLixRuntimeClient(
		env({
			getByName: (name) => {
				assert.equal(name, WORKSPACE_ID);
				return {
					fetch: async (request) => {
						requests.push(request);
						return branchProtocolResponse(request);
					},
				};
			},
		}),
		{ userId: "user-1", token: "secret-oauth-token" },
		async () => {
			authorizationChecks += 1;
			return null;
		},
	);

	assert.equal(await client.activeBranchId(WORKSPACE_ID), "main");
	assert.equal(authorizationChecks, 2);
	assert.deepEqual(
		requests.map((request) => new URL(request.url).pathname),
		[
			`/workspaces/${WORKSPACE_ID}/lix/v1/`,
			`/workspaces/${WORKSPACE_ID}/lix/v1/`,
		],
	);
	for (const request of requests) {
		assert.equal(request.headers.get("authorization"), null);
	}
});

void test("active-branch lookup, branch switch, and execution are queued", async () => {
	const operations: string[] = [];
	const client = new WorkerLixRuntimeClient(
		{},
		{ userId: "user-1", token: "secret-oauth-token" },
		async () => null,
		{
			workspaceFetch: async (_workspaceId, request) => {
				const pathname = new URL(request.url).pathname;
				if (pathname === "/lix/v1/") {
					operations.push("active-branch");
					return branchProtocolResponse(request);
				}
				if (pathname === "/lix/v1/branch/switch") {
					const body: { branchId: string } = await request.json();
					operations.push(`switch:${body.branchId}`);
					return Response.json({ branchId: body.branchId });
				}
				operations.push("execute");
				return Response.json({
					columns: [],
					rows: [],
					rowsAffected: 0,
					notices: [],
				});
			},
		},
	);

	const branchId = await client.activeBranchId(WORKSPACE_ID);
	assert.deepEqual(await client.switchBranch(WORKSPACE_ID, branchId), {
		branchId,
	});
	await client.execute(WORKSPACE_ID, { sql: "SELECT 1" });
	assert.deepEqual(operations, [
		"active-branch",
		"active-branch",
		"switch:main",
		"execute",
	]);
});

void test("transient container failures retry indefinitely with capped jitter and reacquired stubs", async () => {
	let acquisitions = 0;
	let starts = 0;
	let fetches = 0;
	const delays: Array<number> = [];
	const client = new WorkerLixRuntimeClient(
		env({
			getByName: () => {
				acquisitions += 1;
				return {
					startAndWaitForPorts: async () => {
						starts += 1;
						if (starts <= 5) {
							throw new Error(
								"The container is not running, consider calling start()",
							);
						}
					},
					fetch: async (request) => {
						fetches += 1;
						return branchProtocolResponse(request);
					},
				};
			},
		}),
		{ userId: "user-1", token: "secret-oauth-token" },
		async () => null,
		{
			retryRandom: () => 1,
			retryDelay: async (milliseconds) => {
				delays.push(milliseconds);
			},
		},
	);

	assert.equal(await client.activeBranchId(WORKSPACE_ID), "main");
	assert.equal(acquisitions, 7);
	assert.equal(starts, 7);
	assert.equal(fetches, 2);
	assert.deepEqual(delays, [1_000, 2_000, 4_000, 5_000, 5_000]);
});

void test("Durable Object storage resets are retried", async () => {
	let acquisitions = 0;
	const client = new WorkerLixRuntimeClient(
		env({
			getByName: () => {
				acquisitions += 1;
				return {
					startAndWaitForPorts: async () => {
						if (acquisitions === 1) {
							throw new Error(
								"Internal error in Durable Object storage caused object to be reset; reference = retry-me",
							);
						}
					},
					fetch: branchProtocolResponse,
				};
			},
		}),
		{ userId: "user-1", token: "secret-oauth-token" },
		async () => null,
		{ retryDelay: async () => undefined },
	);

	assert.equal(await client.activeBranchId(WORKSPACE_ID), "main");
	assert.equal(acquisitions, 3);
});

void test("transient HTTP responses retry and replay request bodies", async () => {
	let acquisitions = 0;
	const bodies: Array<unknown> = [];
	const delays: Array<number> = [];
	const client = new WorkerLixRuntimeClient(
		env({
			getByName: () => {
				acquisitions += 1;
				return {
					fetch: async (request) => {
						const pathname = testProtocolPath(request);
						if (
							pathname === "/lix/v1/" ||
							pathname === "/lix/v1/branch/switch"
